"""독립 재검토 결과를 근거로 QG0 개발 설계·시험계획만 수용한다."""
import datetime,hashlib,json,pathlib
R=pathlib.Path(__file__).resolve().parents[1];now=datetime.datetime.now().astimezone().isoformat()
review=json.loads((R/'artifacts/qg0-independent-review.json').read_text(encoding='utf-8'));assert review['document_contract_checks']==10
checks=json.loads((R/'artifacts/qg0-review-root-docs-final.json').read_text(encoding='utf-8'));assert checks['failed']==0 and checks['executed']==10
resolution=[{'parent_id':f'QG0-REVIEW-{i:02d}','reviewer_id':f'deleg_fb3bbcbc-P1-{i:02d}','status':'resolved'}for i in range(1,5)]
record={'recorded_at':now,'gate':'QG0','decision':'ACCEPTED_FOR_LOCAL_DEVELOPMENT_DESIGN_AND_TEST_PLAN_ONLY','authority':'사용자의 PartB 별도 개발 지시에 따른 부모 감독자 검토. 사용자의 별도 지원OS/배포/운영변경 승인을 의미하지 않음','independent_recheck':'deleg_149f9737','additional_findings':[],'resolution':resolution,'scope':['같은workspace의별도Quick제품','기존npi-core/npi-probes를공유하는network-core facade','일반사용자기본경로/단일EXE 검증계획','Q-P0-01~13 게이트추적 및 자원/성능/통합검증계획'],'development_decisions':{'architecture':'Win32 native GUI, Windows x64 우선. 라이브러리세부선택은의존성검사전확정아님','max_targets':100,'default_and_max_concurrency':4,'tcp_default_timeout_ms':3000,'default_features':['tcp_connect','icmp_ping'],'quick_schema':'1.0','inspector_schema_unchanged':True,'static_crt':'검토 설정,무설치보장아님'},'not_accepted':['QG1이후제품기능수용','Windows10/11/Server지원인증','일반사용자실행실측','클린VM단일EXE','성능실측','운영망시험/OS설정변경/권한상승'],'reviewed_source_sha256':{}}
for folder in ['docs/quick-check','apps/network-quick-check']:
 for p in (R/folder).glob('*.md'):record['reviewed_source_sha256'][p.relative_to(R).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
out=R/'artifacts/qg0-design-acceptance.json';assert not out.exists();out.write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
review.update(rechecked_at=now,recheck_resolution=resolution,remaining_findings=[],gate_accepted='local development design and test plan only',acceptance_artifact='artifacts/qg0-design-acceptance.json');(R/'artifacts/qg0-independent-review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
state=json.loads((R/'artifacts/quick-check-progress.json').read_text(encoding='utf-8'));state['recorded_at']=now;state['qg0'].update(status='ACCEPTED_DESIGN_AND_TEST_PLAN_ONLY',accepted=True,recheck_findings=0,acceptance_artifact='artifacts/qg0-design-acceptance.json');state['remaining_blockers']=[v for v in state['remaining_blockers']if not v.startswith('QG0 수정')];(R/'artifacts/quick-check-progress.json').write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
# 기존 계획문서의 검토대기 문구는 검토 시점의 기록으로 남기고 이후 수용기록을 별도 명시한다.
for rel in ['docs/quick-check/gates.md','docs/quick-check/decisions.md','apps/network-quick-check/README.md']:
 p=R/rel;prefix='../../'if rel.startswith('docs/')else'../../';p.write_text(p.read_text(encoding='utf-8')+'\n## 후속 QG0 설계 검토 판정\n- '+now+': 독립 재검토 `deleg_149f9737`에서 문서 누락4건 해소/추가확정P1 없음. 부모 감독자가 **로컬 개발 설계·시험계획 범위만 수용**했다. 위의 제안/검토대기는 최초 작성 시점이며 후속 판정 근거는 `artifacts/qg0-design-acceptance.json`이다.\n- 실제 일반사용자 실행·지원OS·단일EXE/VM·성능과 QG1 이후 기능 수용은 별개로 미검증이다. 운영 설정 변경 권한을 부여하지 않는다. CRT 정적링크는 여전히 검토 설정이다.\n',encoding='utf-8',newline='\n')
print(json.dumps({'gate':record['gate'],'decision':record['decision'],'resolved':len(resolution),'new_findings':0},ensure_ascii=False))
